#include <iostream>

class Circle {
public:
    Circle() : radius(1.0) {}
    explicit Circle(double r) : radius((r >= 0.0) ? r : 0.0) {}

    // Const member function: guarantees no mutation of fields
    [[nodiscard]] double getRadius() const {
        return radius;
    }

    [[nodiscard]] double getArea() const {
        constexpr double PI = 3.141592653589793;
        return radius * radius * PI;
    }

    void setRadius(double newRadius) {
        radius = (newRadius >= 0.0) ? newRadius : 0.0;
    }

private:
    double radius;
};

// Efficient pass-by-const-reference: avoids copying and guarantees immutability
void printCircle(const Circle& c) {
    std::cout << "Radius: " << c.getRadius() << ", Area: " << c.getArea() << "\n";
}

int main() {
    Circle c1(2.5);
    printCircle(c1);

    c1.setRadius(4.0);
    printCircle(c1);

    return 0;
}

#include <iostream>
#include <string>
#include <utility>

class BMI {
public:
    BMI(std::string newName, int newAge, double newWeight, double newHeight)
        : name(std::move(newName)), age(newAge), weight(newWeight), height(newHeight) {}

    BMI(std::string newName, double newWeight, double newHeight)
        : BMI(std::move(newName), 20, newWeight, newHeight) {} // Delegating constructor (C++11)

    [[nodiscard]] double getBMI() const {
        constexpr double KILOGRAMS_PER_POUND = 0.45359237;
        constexpr double METERS_PER_INCH = 0.0254;
        double weightInKg = weight * KILOGRAMS_PER_POUND;
        double heightInM = height * METERS_PER_INCH;
        return weightInKg / (heightInM * heightInM);
    }

    [[nodiscard]] std::string getStatus() const {
        double bmi = getBMI();
        if (bmi < 18.5) return "Underweight";
        if (bmi < 25.0) return "Normal";
        if (bmi < 30.0) return "Overweight";
        return "Obese";
    }

    [[nodiscard]] const std::string& getName() const { return name; }
    [[nodiscard]] int getAge() const { return age; }
    [[nodiscard]] double getWeight() const { return weight; }
    [[nodiscard]] double getHeight() const { return height; }

private:
    std::string name;
    int age;
    double weight; // in pounds
    double height; // in inches
};

int main() {
    BMI bmi1("John Doe", 18, 145.0, 70.0);
    std::cout << "The BMI for " << bmi1.getName() << " is "
              << bmi1.getBMI() << " " << bmi1.getStatus() << "\n";

    BMI bmi2("Susan King", 215.0, 70.0);
    std::cout << "The BMI for " << bmi2.getName() << " is "
              << bmi2.getBMI() << " " << bmi2.getStatus() << "\n";

    return 0;
}
